function enumerateTree(tree) {
  if (!Array.isArray(tree)) return [tree];
  return tree.reduce((acc, sub) => acc.concat(enumerateTree(sub)), []);
}

const tree = [[1, 2], 3, [4, [5, 6]]];
const result = enumerateTree(tree)
  .filter((x) => x % 2 === 1)
  .map((x) => x * x)
  .reduce((sum, x) => sum + x, 0);

console.log(result);

